#include <stdio.h>  int main() {     int n, i;     int bt[20], wt[20], tat[20];      float avg_wt = 0, avg_tat = 0;      // Number of processes     printf("Enter number of processes: ");     scanf("%d", &n);      // Enter burst time     printf("Enter burst time:\n");      for(i = 0; i < n; i++)     {         printf("P%d: ", i + 1);         scanf("%d", &bt[i]);     }      // Waiting time of first process     wt[0] = 0;      // Calculate waiting time     for(i = 1; i < n; i++)     {         wt[i] = wt[i - 1] + bt[i - 1];     }      // Calculate turnaround time     for(i = 0; i < n; i++)     {         tat[i] = wt[i] + bt[i];     }      // Calculate averages     for(i = 0; i < n; i++)     {         avg_wt = avg_wt + wt[i];         avg_tat = avg_tat + tat[i];     }      avg_wt = avg_wt / n;     avg_tat = avg_tat / n;      // Display results     printf("\nProcess\tBT\tWT\tTAT\n");      for(i = 0; i < n; i++)     {         printf("P%d\t%d\t%d\t%d\n",                i + 1, bt[i], wt[i], tat[i]);     }      printf("\nAverage Waiting Time = %.2f", avg_wt);     printf("\nAverage Turnaround Time = %.2f\n", avg_tat);      return 0; }


